import os
import re
import shutil
import traceback

from typing import List

from taf.rfrl.common_resources.oam_kpi.report_oam_kpi import report_oam_kpi, ReportOamKpi
from taf.ul.oam_kpi_calculations import oam_kpi_calculations
from taf.ul.oam_kpi_calculations.exceptions import OamKpiCalculationsException
from taf.ul.oam_kpi_calculations.utilities import get_last_disconnected_ims_log

from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class CSV4AllOamKpi:

    def __init__(self, kpi_names: List[str], log_dir=None, kpi_targets=None):
        self.log_dir = log_dir
        self.kpi_calc = oam_kpi_calculations()
        self.kpi_calc.log_warning = False
        self.kpi_names = kpi_names
        self.kpi_results = []
        self.kpi_targets = kpi_targets
        self.uboot_downgrade = False
        self.inter_release_update = None
        self.kpi_calc.clear_results()

    def calculate_test_success_ratio(self, test_results) -> None:
        if not any(kpi_id in self.kpi_names for kpi_id in ["kpi16", "kpi17", "kpi5"]):
            succes_ratio_kpi = self.kpi_names[0][:-1]
        else:
            succes_ratio_kpi = self.kpi_names[0]
        passed_iterations = sum(nodes_results == "passed" for nodes_results in test_results.values())
        executed_iterations = sum(1 for nodes_results in test_results.values() if nodes_results)
        test_logger(f"Passed iterations: {passed_iterations}, executed iterations: {executed_iterations}")
        self.kpi_results = self.get_kpi_results()
        ReportOamKpi().report_oam_kpi_success_rate(kpi_name=succes_ratio_kpi,
                                                   passed_iterations=passed_iterations,
                                                   executed_iterations=executed_iterations)
        self.kpi_results.append({"id": ReportOamKpi()._get_success_rate_kpi_id(succes_ratio_kpi),
                                 "value": str(passed_iterations),
                                 "target": str(executed_iterations),
                                 "source": "OAMKPI"})

    def get_kpi_results(self):
        return ReportOamKpi().prepare_kpi_results(oam_kpi_results=self.kpi_calc.get_results(),
                                                  log_warn=False,
                                                  oam_kpi_targets=self.kpi_targets)

    def set_start_timestamp_for_kpi_calculation(self):
        self.kpi_calc.save_search_start_timestamp()

    def set_end_timestamp_for_kpi_calculation(self):
        self.kpi_calc.save_search_end_timestamp()

    @method_decorator()
    def calculate_kpi(self, ims_files):
        self.kpi_calc.calculate_kpis(kpi_names=self.kpi_names, ims_file_path=ims_files)

    @method_decorator()
    def calculate_proper_oam_kpi(self, ims_path: str) -> None:
        ims_files = sorted(["/".join([ims_path, ims_file]) for ims_file in os.listdir(ims_path)
                            if re.match(r"OAM_KPI_MRBTS.*_\d.ims2", ims_file)])

        try:
            self.calculate_kpi(ims_files)
        except OamKpiCalculationsException as kpi_exception:
            test_logger(kpi_exception, "warn")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

        calculated_kpis = self.kpi_calc.get_latest_results()
        self.kpi_calc.save_results_to_file(os.path.join(os.path.dirname(ims_path), 'kpi_results.json'))
        self.report_oam_kpi(calculated_kpis)

    @method_decorator()
    def report_oam_kpi(self, calculated_kpis):
        report_oam_kpi(oam_kpi_results=calculated_kpis, log_warn=False, oam_kpi_targets=self.kpi_targets)

    def clear_kpi_results(self) -> None:
        self.kpi_calc.clear_results()

    def get_uuf_kpi(self, test_type):
        try:
            if test_type == "reset":
                return str(self.kpi_calc.get_all_deltas("kpi1a")[-1])
            if test_type in ["upgrade", "activation_reset"]:
                return str(self.kpi_calc.get_all_deltas(self.kpi_names[0])[-1])
        except Exception as exception:
            test_logger("Given KPI not found in deltas", "error")
            test_logger(exception, "info", False)
            return

    @staticmethod
    @method_decorator()
    def get_latest_disconnected_ims_file(source_log_dir, log_name_regex, target_ims_file):
        latest_ims_path = get_last_disconnected_ims_log(source_log_dir, log_name_regex)
        test_logger(f"mv {latest_ims_path} to {target_ims_file}", console=False)
        os.makedirs(target_ims_file.rsplit('/', 1)[0], exist_ok=True)
        shutil.move(latest_ims_path, target_ims_file)
